//! Replays the lifecycle's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave,
//! compared as text. The cases are read against the installed tree kept
//! under `fixtures/upstream/`. The corpus is regenerated by
//! `tools/oracle/refresh.sh`; nothing here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_harness::Harness;
use focus_js::json::stringify;
use focus_lifecycle::oracle::{KINDS, run_case};
use focus_lifecycle::workflow::Workflow;
use focus_workspace::Layout;
use focus_workspace::records::{Invoker, Selection};
use serde_json::{Value, json};

#[test]
fn every_lifecycle_case_gets_upstreams_answer() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
    // Nothing is written: the install is read where the fixtures keep it.
    let wf = Workflow::open(
        Layout::new(fixtures.join("upstream/installed/claude"), Harness::Claude),
        Selection {
            space: "default".to_owned(),
            intent: None,
            session_id: None,
            binding: None,
        },
        Invoker::default(),
    )
    .unwrap();
    let dir = fixtures.join("oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.split('\n').filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.split('\n').filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut windows, mut floored, mut unfloored, mut merged, mut open) = (0, 0, 0, 0, 0);
    let (mut counts, mut refused, mut still_pending, mut closed) = (0, 0, 0, 0);
    let (mut ambiguous, mut started_again, mut recovered, mut in_a_bolt) = (0, 0, 0, 0);
    let (mut snapshots, mut fingerprinted, mut whole, mut appended) = (0, 0, 0, 0);
    let (mut two_views, mut converted, mut came_after) = (0, 0, 0);
    let (mut current, mut unreadable, mut replaceable) = (0, 0, 0);
    let (mut retried, mut unrecordable) = (0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default();
        if !KINDS.contains(&kind) {
            continue;
        }
        // A case with a link or a second name in it needs a platform where a
        // link is a file and a file says how many names it has.
        let has = |key: &str| case[key].as_object().is_some_and(|map| !map.is_empty());
        // And one marked `posix` rests on what such a host says of a path
        // that goes through a file.
        if cfg!(windows) && (has("links") || has("hard") || case["posix"] == true) {
            continue;
        }
        let out = run_case(&wf, &case);
        let some = |key: &str| out[key].as_array().is_some_and(|list| !list.is_empty());
        if kind == "review_snapshot" {
            snapshots += 1;
            fingerprinted += usize::from(out["fingerprint"].is_string());
            let taken = &out["snapshot"];
            whole += usize::from(taken.is_object());
            appended += usize::from(taken["appendix"][0].as_u64().is_some_and(|len| len > 0));
            two_views += usize::from(
                taken["bodies"]
                    .as_array()
                    .is_some_and(|views| views.len() == 2),
            );
            converted += usize::from(taken["raw"][0].is_string());
            came_after += usize::from(out["told"][1][0][1] == true);
            assert!(out.get("error").is_none(), "{}: {out}", case["id"]);
            // What can be done with a pending request: three flags for
            // each way of asking each request (44 or 28 of a stage that
            // writes the workspace, 12 of another; two ways, and a third
            // for the first eight), then four flags for each request as the
            // oldest pending one.
            let flags = |key: &str| out["pending"][key].as_str().unwrap_or_default().as_bytes();
            let (currency, status) = (flags("currency"), flags("status"));
            assert!(
                matches!(
                    (currency.len(), status.len()),
                    (288, 176) | (192, 112) | (96, 48)
                ),
                "{}: {out}",
                case["id"]
            );
            let any = |rows: &[u8], width: usize, wanted: &[u8]| {
                rows.chunks(width).any(|row| row == wanted)
            };
            current += usize::from(any(currency, 3, b"111"));
            unreadable += usize::from(any(currency, 3, b"100"));
            replaceable += usize::from(any(status, 4, b"0001"));
            retried += usize::from(any(status, 4, b"1010"));
            unrecordable += usize::from(any(status, 4, b"1100"));
        } else if kind == "review_accounting" {
            counts += 1;
            refused += usize::from(out.get("error").is_some());
            let waiting = out["pending"].as_array().map_or(0, Vec::len) as u64;
            let asked = out["requests"].as_u64().unwrap_or_default();
            still_pending += usize::from(waiting > 0);
            closed += usize::from(asked > waiting);
            ambiguous += usize::from(out["ambiguity"].is_string());
            started_again += usize::from(out["budgeted"].as_u64().unwrap_or_default() < asked);
            recovered += usize::from(out["recovery"][1] == true);
            in_a_bolt += usize::from(out["bolt"][0] == true);
        } else {
            windows += 1;
            floored += usize::from(out["floor"].as_i64().is_some_and(|floor| floor >= 0));
            unfloored += usize::from(out["floor"] == -1);
            merged += usize::from(some("merged"));
            open += usize::from(some("open"));
        }
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    // Enough cases, and enough of them on each side of every answer.
    assert!(
        windows >= 1900 && floored >= 1400 && unfloored >= 400,
        "{windows} {floored} {unfloored}"
    );
    assert!(merged >= 280 && open >= 580, "{merged} {open}");
    assert!(
        cfg!(windows) || (counts >= 1150 && refused >= 40 && still_pending >= 500 && closed >= 250),
        "{counts} {refused} {still_pending} {closed}"
    );
    assert!(
        ambiguous >= 200 && started_again >= 20 && recovered >= 40 && in_a_bolt >= 20,
        "{ambiguous} {started_again} {recovered} {in_a_bolt}"
    );
    assert!(
        cfg!(windows)
            || (snapshots >= 1250
                && fingerprinted >= 900
                && snapshots - fingerprinted >= 300
                && whole >= 640),
        "{snapshots} {fingerprinted} {whole}"
    );
    assert!(
        cfg!(windows)
            || (appended >= 210 && two_views >= 150 && converted >= 240 && came_after >= 210),
        "{appended} {two_views} {converted} {came_after}"
    );
    assert!(
        cfg!(windows)
            || (current >= 650
                && unreadable >= 240
                && replaceable >= 650
                && retried >= 240
                && unrecordable >= 650),
        "{current} {unreadable} {replaceable} {retried} {unrecordable}"
    );
    assert!(
        differing.is_empty(),
        "{} lifecycle cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
